CustomField.formula:
if(Total_Monthly_Budget__c>9000, 
	"**Monthly Budget > 9000 = 15pts**", 
	"Monthly Budget > 9000 = 15pts")&BR()&
if(Total_Monthly_Budget__c<=9000 && Total_Monthly_Budget__c>7000, 
	"**Monthly Budget <= 9000 and > 7000 = 10pts**", 
	"Monthly Budget <= 9000 and > 7000 = 10pts")&BR()&
if(Total_Monthly_Budget__c<=7000 && Total_Monthly_Budget__c>3000, 
	"**Monthly Budget <= 7000 and > 3000 = 5pts**", 
	"Monthly Budget <= 7000 and > 3000 = 5pts")&BR()&
if(Total_Monthly_Budget__c<=3000, 
	"**Monthly Budget <= 3000 = 0pts**", 
	"Monthly Budget <= 3000 = 0pts")
